param([string]$SavePath=(Join-Path $PSScriptRoot '../../.local-research/runtime/profile-20261102/Saves/survival-stopped-b.rws'))
# Read-only XML extraction. Missing numeric save fields use their serialized zero default;
# presence is retained for Food. No target assembly execution or compressed-map decoding.
$ErrorActionPreference='Stop'
$s=[xml](Get-Content -Raw -LiteralPath $SavePath)
function Num($node){if($null -eq $node){return 0.0};[double]::Parse($node.InnerText,[Globalization.CultureInfo]::InvariantCulture)}
function Stack($node){if($node.SelectSingleNode('stackCount')){return [int]$node.stackCount};1}
function Pawn($id){
 $p=$s.SelectSingleNode("//thing[id='$id']");$food=$p.SelectSingleNode('needs/needs/li[def="Food"]/curLevel');$d=$p.SelectSingleNode('jobs/curDriver')
 [ordered]@{id=$id;nick=[string]$p.name.nick;pos=[string]$p.pos;health_state_explicit=[string]$p.healthTracker.healthState;food=(Num $food);food_field_present=($null -ne $food);hediffs=@($p.SelectNodes('healthTracker/hediffSet/hediffs/li')|ForEach-Object{[ordered]@{def=[string]$_.def;severity=(Num $_.SelectSingleNode('severity'));age_ticks=[int]$_.ageTicks;tick_added=[int]$_.tickAdded}});job=[ordered]@{def=[string]$p.jobs.curJob.def;target_a=[string]$p.jobs.curJob.targetA;target_b=[string]$p.jobs.curJob.targetB;driver=[string]$d.Class;toil_index=[int]$d.curToilIndex;ticks_left=[int]$d.ticksLeftThisToil;start_tick=[int]$d.startTick};carried=@($p.SelectNodes('carryTracker/innerContainer/innerList/li')|ForEach-Object{[ordered]@{id=[string]$_.id;def=[string]$_.def;count=(Stack $_)}});rescued_memories=@($p.SelectNodes('needs/needs/li[def="Mood"]/thoughts/memories/memories/li[def="RescuedMe"]')|ForEach-Object{[ordered]@{other_pawn=[string]$_.otherPawn;opinion_offset=[int]$_.opinionOffset;age=[int]$_.age}});work_priority_values=@($p.SelectNodes('workSettings/priorities/vals/li')|ForEach-Object{[int]$_.InnerText})}
}
$meals=@($s.SelectNodes('//*[def="MealSurvivalPack" and id]')|ForEach-Object{[ordered]@{id=[string]$_.id;count=(Stack $_);pos=[string]$_.pos;carrier=if($_.ParentNode.Name -eq 'innerList' -and $_.ParentNode.ParentNode.ParentNode.Name -eq 'carryTracker'){[string]$_.ParentNode.ParentNode.ParentNode.ParentNode.id}else{''};forbidden=([string]$_.forbidden -eq 'True')}}|Sort-Object {$_.id})
$beds=@($s.SelectNodes('//thing[def="Bed"]')|ForEach-Object{[ordered]@{id=[string]$_.id;pos=[string]$_.pos;stuff=[string]$_.stuff;health=[int]$_.health;medical=([string]$_.medical -eq 'True');spawned_tick=[int]$_.spawnedTick}})
[ordered]@{file=(Split-Path -Leaf $SavePath);sha256=(Get-FileHash -LiteralPath $SavePath -Algorithm SHA256).Hash.ToLowerInvariant();bytes=(Get-Item -LiteralPath $SavePath).Length;version=$s.SelectSingleNode('//meta/gameVersion').InnerText;mods=@($s.SelectNodes('//meta/modIds/li')|ForEach-Object{$_.InnerText});tick=[int]$s.SelectSingleNode('//tickManager/ticksGame').InnerText;patient=(Pawn 'Human965');rescuer=(Pawn 'Human958');beds=$beds;meals=$meals;meal_total=($meals|Measure-Object -Property count -Sum).Sum;scope='Explicit XML with missing numeric zero defaults; Food field presence retained. Work priorities remain an undecoded ordered value vector. No gameplay execution.'}|ConvertTo-Json -Depth 16
